CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, checksum TEXT NOT NULL, appliedAt INTEGER NOT NULL);
CREATE TABLE projects(id TEXT PRIMARY KEY, name TEXT NOT NULL, root TEXT, mode TEXT NOT NULL CHECK(mode IN ('demo','live','observe')), version INTEGER NOT NULL DEFAULT 1, createdAt INTEGER NOT NULL);
CREATE TABLE identities(id TEXT PRIMARY KEY, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','operator','reviewer','viewer','agent','runner')), tokenHash TEXT NOT NULL UNIQUE, projectIds TEXT NOT NULL CHECK(json_valid(projectIds)), agentId TEXT, machineId TEXT, revokedAt INTEGER, createdAt INTEGER NOT NULL, expiresAt INTEGER);
CREATE TABLE browser_sessions(tokenHash TEXT PRIMARY KEY, identityId TEXT NOT NULL REFERENCES identities(id), csrfHash TEXT NOT NULL, expiresAt INTEGER NOT NULL);
CREATE TABLE agents(id TEXT PRIMARY KEY, projectId TEXT NOT NULL REFERENCES projects(id), name TEXT NOT NULL, role TEXT NOT NULL, provider TEXT NOT NULL, mode TEXT NOT NULL, species TEXT NOT NULL, color TEXT NOT NULL, activity TEXT NOT NULL, version INTEGER NOT NULL, createdAt INTEGER NOT NULL, lastSeen INTEGER, UNIQUE(id,projectId));
CREATE INDEX agents_project ON agents(projectId);
CREATE TABLE work_items(id TEXT PRIMARY KEY, projectId TEXT NOT NULL REFERENCES projects(id), title TEXT NOT NULL, description TEXT NOT NULL, acceptance TEXT NOT NULL, state TEXT NOT NULL, assignee TEXT, version INTEGER NOT NULL, priority INTEGER NOT NULL, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL, attempt INTEGER NOT NULL, result TEXT, submittedBy TEXT, headSha TEXT, reviewBy TEXT, verifiedSha TEXT, UNIQUE(id,projectId), FOREIGN KEY(assignee,projectId) REFERENCES agents(id,projectId));
CREATE INDEX work_project_state ON work_items(projectId,state,priority,createdAt);
CREATE TABLE task_dependencies(workId TEXT NOT NULL, dependsOn TEXT NOT NULL, projectId TEXT NOT NULL, PRIMARY KEY(workId,dependsOn), CHECK(workId<>dependsOn), FOREIGN KEY(workId,projectId) REFERENCES work_items(id,projectId), FOREIGN KEY(dependsOn,projectId) REFERENCES work_items(id,projectId));
CREATE TABLE messages(id TEXT PRIMARY KEY, projectId TEXT NOT NULL REFERENCES projects(id), threadId TEXT NOT NULL, replyTo TEXT, senderId TEXT NOT NULL, body TEXT NOT NULL, kind TEXT NOT NULL, createdAt INTEGER NOT NULL, expiresAt INTEGER NOT NULL, UNIQUE(id,projectId), FOREIGN KEY(replyTo,projectId) REFERENCES messages(id,projectId));
CREATE INDEX messages_thread ON messages(projectId,threadId,createdAt);
CREATE TABLE recipient_deliveries(sequence INTEGER PRIMARY KEY AUTOINCREMENT, messageId TEXT NOT NULL, projectId TEXT NOT NULL, recipientId TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('available','injected','acknowledged','responded','failed','expired','cancelled')), acknowledgedAt INTEGER, attempts INTEGER NOT NULL DEFAULT 0, lastError TEXT, UNIQUE(messageId,recipientId), FOREIGN KEY(messageId,projectId) REFERENCES messages(id,projectId), FOREIGN KEY(recipientId,projectId) REFERENCES agents(id,projectId));
CREATE INDEX deliveries_inbox ON recipient_deliveries(projectId,recipientId,state,sequence);
CREATE TABLE events(seq INTEGER PRIMARY KEY AUTOINCREMENT, eventId TEXT NOT NULL UNIQUE, projectId TEXT NOT NULL REFERENCES projects(id), type TEXT NOT NULL, actorId TEXT NOT NULL, occurredAt INTEGER NOT NULL, ingestedAt INTEGER NOT NULL, correlationId TEXT NOT NULL, causationId TEXT NOT NULL, source TEXT NOT NULL, dataClassification TEXT NOT NULL DEFAULT 'project', payload TEXT NOT NULL CHECK(json_valid(payload)), schemaVersion INTEGER NOT NULL DEFAULT 1);
CREATE INDEX events_project_seq ON events(projectId,seq);
CREATE TABLE outbox(id TEXT PRIMARY KEY, eventId TEXT NOT NULL REFERENCES events(eventId), projectId TEXT NOT NULL REFERENCES projects(id), state TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, availableAt INTEGER NOT NULL, leaseOwner TEXT, leaseUntil INTEGER, lastError TEXT);
CREATE TABLE command_journal(id TEXT PRIMARY KEY, identityId TEXT NOT NULL, idempotencyKey TEXT NOT NULL, requestHash TEXT NOT NULL, result TEXT NOT NULL CHECK(json_valid(result)), createdAt INTEGER NOT NULL, UNIQUE(identityId,idempotencyKey));
CREATE TABLE machines(id TEXT PRIMARY KEY, name TEXT NOT NULL, projectIds TEXT NOT NULL CHECK(json_valid(projectIds)), lastSeen INTEGER NOT NULL, state TEXT NOT NULL, concurrency INTEGER NOT NULL CHECK(concurrency BETWEEN 1 AND 16), revokedAt INTEGER);
CREATE TABLE runs(id TEXT PRIMARY KEY, projectId TEXT NOT NULL REFERENCES projects(id), workId TEXT NOT NULL REFERENCES work_items(id), agentId TEXT NOT NULL REFERENCES agents(id), machineId TEXT REFERENCES machines(id), provider TEXT NOT NULL, mode TEXT NOT NULL, state TEXT NOT NULL, epoch INTEGER NOT NULL DEFAULT 1, providerSessionId TEXT, processIdentity TEXT, createdAt INTEGER NOT NULL, lastSeen INTEGER, result TEXT);
CREATE UNIQUE INDEX one_active_run ON runs(workId) WHERE state IN ('queued','claimed','running','cancel_requested','indeterminate');
CREATE TABLE runner_commands(id TEXT PRIMARY KEY, runId TEXT NOT NULL REFERENCES runs(id), projectId TEXT NOT NULL REFERENCES projects(id), state TEXT NOT NULL DEFAULT 'queued', epoch INTEGER NOT NULL, machineId TEXT REFERENCES machines(id), leaseUntil INTEGER, createdAt INTEGER NOT NULL);
CREATE INDEX runner_commands_ready ON runner_commands(state,createdAt);
CREATE TABLE runner_reports(sourceEventId TEXT PRIMARY KEY, machineId TEXT NOT NULL REFERENCES machines(id), runId TEXT NOT NULL REFERENCES runs(id), receivedAt INTEGER NOT NULL);
CREATE TABLE layouts(projectId TEXT PRIMARY KEY REFERENCES projects(id), version INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), updatedAt INTEGER NOT NULL);
CREATE TABLE knowledge(id TEXT PRIMARY KEY, projectId TEXT NOT NULL REFERENCES projects(id), title TEXT NOT NULL, body TEXT NOT NULL, source TEXT NOT NULL, author TEXT NOT NULL, classification TEXT NOT NULL, version INTEGER NOT NULL, createdAt INTEGER NOT NULL);
CREATE TABLE reviews(id TEXT PRIMARY KEY, workId TEXT NOT NULL REFERENCES work_items(id), projectId TEXT NOT NULL REFERENCES projects(id), author TEXT NOT NULL, decision TEXT NOT NULL, body TEXT NOT NULL, headSha TEXT, createdAt INTEGER NOT NULL);
CREATE TABLE approval_decisions(id TEXT PRIMARY KEY, projectId TEXT NOT NULL REFERENCES projects(id), runId TEXT NOT NULL REFERENCES runs(id), providerRequestId TEXT NOT NULL, actionHash TEXT NOT NULL, parameters TEXT NOT NULL CHECK(json_valid(parameters)), expiresAt INTEGER NOT NULL, decision TEXT, decidedBy TEXT, decidedAt INTEGER, providerAcknowledgedAt INTEGER);
CREATE TABLE projection_checkpoints(projectId TEXT NOT NULL REFERENCES projects(id), name TEXT NOT NULL, seq INTEGER NOT NULL, PRIMARY KEY(projectId,name));
CREATE TABLE runner_cursors(machineId TEXT PRIMARY KEY REFERENCES machines(id), lastAck TEXT NOT NULL);
